begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_table('public','vehicles','Canonical vehicles exist');
select ok((select relrowsecurity from pg_class where oid='public.vehicles'::regclass),'Vehicle RLS is enabled');
select ok(not has_function_privilege('authenticated','public.finalize_vehicle_run(uuid,uuid,uuid,jsonb)','execute'),'Owners cannot forge worker finalization');
select ok(not has_table_privilege('anon','public.vehicle_search_profiles','select'),'Anonymous callers cannot read profiles');
insert into auth.users(id) values('00000000-0000-4000-8000-000000000071'),('00000000-0000-4000-8000-000000000072');
insert into public.workers(id,user_id,name,token_hash) values('00000000-0000-4000-8000-000000000073','00000000-0000-4000-8000-000000000071','Vehicle test',repeat('b',64));
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000071',true);
create temp table vehicle_test_context(profile uuid,schedule uuid,task uuid,run uuid,lease uuid);
insert into vehicle_test_context(profile) select public.save_vehicle_profile(null,'{"make":"Rivian","model":"R1T","origin_zip":"46530","cost_ceiling":70000,"allowed_batteries":["large","max"]}');
update vehicle_test_context c set schedule=p.schedule_id from public.vehicle_search_profiles p where p.id=c.profile;
select is((select s.enabled from public.task_schedules s join vehicle_test_context c on c.schedule=s.id),false,'Initial vehicle schedule is disabled');
select throws_ok($$update public.task_schedules set enabled=true where id=(select schedule from vehicle_test_context)$$,'P0001','Complete and review a successful manual baseline for this search scope before enabling daily searches','Shared schedule controls cannot bypass the vehicle baseline');
select is((select count(*)::integer from public.vehicle_profile_versions p join vehicle_test_context c on c.profile=p.profile_id),1,'Profile revision is immutable domain data');
update vehicle_test_context set task=public.run_task_schedule(schedule,'00000000-0000-4000-8000-000000000074');
update vehicle_test_context c set run=r.id from public.runs r where r.task_id=c.task;
select is((select t.job_kind from public.tasks t join vehicle_test_context c on c.task=t.id),'vehicle_search','Occurrence snapshots job kind');
select is((select r.job_payload->>'profile_version' from public.runs r join vehicle_test_context c on c.run=r.id),'1','Run snapshots profile version');
select is((select count(*)::integer from public.claim_next_run('00000000-0000-4000-8000-000000000073')),0,'Legacy worker cannot claim vehicle job');
select public.claim_vehicle_run('00000000-0000-4000-8000-000000000073');
update vehicle_test_context c set lease=r.vehicle_lease from public.runs r where r.id=c.run;
select ok((select lease is not null from vehicle_test_context),'Claim issues a lease token');
select throws_ok($$select public.stage_vehicle_batch(run,'00000000-0000-4000-8000-000000000073',gen_random_uuid(),0,'[]') from vehicle_test_context$$,'P0001','Active vehicle run not found','Wrong lease cannot stage data');
select public.stage_vehicle_batch(run,'00000000-0000-4000-8000-000000000073',lease,0,'[{"source":"auto.dev","source_listing_id":"7FCTGAAA0NN000001","vin":"7FCTGAAA0NN000001","make":"Rivian","model":"R1T","price":50000,"attributes":{"battery_pack":"large"},"availability":"available","eligibility":"needs_verification"}]') from vehicle_test_context;
select is((select count(*)::integer from public.vehicles),0,'Staged batches are not visible inventory');
select is((select public.finalize_vehicle_run(run,'00000000-0000-4000-8000-000000000073',lease,'{"status":"success","scope":{"make":"Rivian","model":"R1T","origin_zip":"46530"},"counts":{"parsed":1,"reported":2,"invalid":0,"duplicates":0},"warnings":[]}')->>'status' from vehicle_test_context),'partial','Count discrepancy downgrades success');
select is((select t.status::text from public.tasks t join vehicle_test_context c on c.task=t.id),'waiting','Partial coverage remains waiting');
select is((select count(*)::integer from public.vehicles),1,'One canonical VIN ingested');
select lives_ok($$select public.finalize_vehicle_run(run,'00000000-0000-4000-8000-000000000073',lease,'{}') from vehicle_test_context$$,'Repeated finalization is idempotent');
select is((select count(*)::integer from public.vehicle_listing_observations),1,'Retry creates no duplicate observation');
select public.set_vehicle_decision(id,'passed',decision_revision) from public.vehicles;
select is((select decision from public.vehicles),'passed','Pass is durable domain data');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000072',true);
select is((select count(*)::integer from public.vehicles),0,'RLS hides another owner vehicles');
select is((select count(*)::integer from public.vehicle_listings),0,'RLS hides another owner listings');
select is((select count(*)::integer from public.vehicle_search_profiles),0,'RLS hides another owner profiles');
reset role;
select * from finish();
rollback;
